-- Plugin API support (docs/api-contract.md): public commit hashes, file roles, idempotency keys,
-- and the branch name rule. Generated by prisma migrate diff, plus the hand-written section at the end.

-- CreateEnum
CREATE TYPE "file_role" AS ENUM ('PRIMARY', 'NATIVE', 'ATTACHMENT');

-- AlterTable
ALTER TABLE "commits" ADD COLUMN     "hash" CHAR(64) NOT NULL;

-- AlterTable
ALTER TABLE "commit_files" ADD COLUMN     "role" "file_role" NOT NULL DEFAULT 'PRIMARY';

-- CreateTable
CREATE TABLE "idempotency_keys" (
    "user_id" UUID NOT NULL,
