-- ─── Hand-written: constraints Prisma can't express ─────────────────────────

-- Lowercase hex SHA-256, so prefix lookups (hash LIKE 'abc1234%') are case-exact.
ALTER TABLE "commits" ADD CONSTRAINT "commits_hash_check" CHECK ("hash" ~ '^[0-9a-f]{64}$');
ALTER TABLE "idempotency_keys" ADD CONSTRAINT "idempotency_keys_request_hash_check" CHECK ("request_hash" ~ '^[0-9a-f]{64}$');

-- Same rule as branchNameSchema in src/lib/api/contract.ts: 1-64 of A-Z a-z 0-9 . _ - /, and valid as a git
-- ref name (no leading / or ., no trailing / or .lock, no .. or //).
ALTER TABLE "branches" ADD CONSTRAINT "branches_name_check" CHECK (
  "name" COLLATE "C" ~ '^[A-Za-z0-9._/-]{1,64}$'
  AND "name" COLLATE "C" !~ '(^[/.])|(/$)|(\.\.)|(//)|(\.lock$)'
);

-- Supabase exposes public tables through its Data API; RLS with no policies blocks that access.
ALTER TABLE "idempotency_keys" ENABLE ROW LEVEL SECURITY;
